<?php $title = __('Day Book'); ?>
<form method="get" class="toolbar"><input type="hidden" name="r" value="reports/day-book"><input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><button class="btn btn-primary" type="submit"><?= __('Filter') ?></button><a class="btn btn-outline" href="<?= e(url('reports/day-book', ['from' => $from, 'to' => $to, 'export' => 'csv'])) ?>"><?= __('CSV') ?></a><button class="btn btn-outline no-print" type="button" onclick="window.print()"><?= __('🖨 Print') ?></button></form>
<div class="panel print-area"><div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Date') ?></th><th><?= __('Entry') ?></th><th><?= __('Type') ?></th><th><?= __('Reference') ?></th><th><?= __('Memo') ?></th><th class="num"><?= __('Debit') ?></th><th class="num"><?= __('Credit') ?></th></tr></thead>
<tbody><?php $td = 0; $tc = 0; foreach ($rows as $r): $td += (float)$r['debit']; $tc += (float)$r['credit']; ?>
<tr><td><?= date_display($r['date']) ?></td><td class="mono"><?= e($r['entry_no']) ?></td><td><span class="badge gray"><?= e($r['voucher_type']) ?></span></td><td><?= e(($r['reference_type'] ?? 'manual') . ($r['reference_id'] ? ' #' . $r['reference_id'] : '')) ?></td><td style="max-width:280px"><?= e($r['memo'] ?? '') ?></td><td class="num"><?= number_format($r['debit'], 2) ?></td><td class="num"><?= number_format($r['credit'], 2) ?></td></tr>
<?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="7" class="muted"><?= __('No entries in range.') ?></td></tr><?php endif; ?></tbody>
<tfoot><tr><th colspan="5"><?= __('TOTALS') ?></th><th class="num"><?= number_format($td, 2) ?></th><th class="num"><?= number_format($tc, 2) ?></th></tr></tfoot></table></div></div>
